css:
.loader { width: var(--loader-size); height: calc(var(--loader-size) * .09); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 16%, transparent); overflow: hidden; }
.loader span { display: block; height: 100%; width: 72%; border-radius: 9999px; background-color: var(--loader-color); background-image: repeating-linear-gradient(45deg, rgba(255, 255, 255, .35) 0 25%, transparent 0 50%); background-size: calc(var(--loader-size) * .12) calc(var(--loader-size) * .12); animation: twStripes var(--loader-speed) linear infinite; }
@keyframes twStripes { to { background-position: calc(var(--loader-size) * .12) 0; } }
